let handle;
export async function openDB(){if(handle)return handle;handle=await new Promise((resolve,reject)=>{const q=indexedDB.open('little-objects',1);q.onupgradeneeded=()=>{const d=q.result;d.createObjectStore('profiles',{keyPath:'id'});d.createObjectStore('sessions',{keyPath:'id'}).createIndex('profileId','profileId');const e=d.createObjectStore('events',{keyPath:'id'});e.createIndex('profileId','profileId');e.createIndex('sessionId','sessionId');};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});return handle;}
export async function put(store,value){const db=await openDB();return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).put(value);t.oncomplete=()=>resolve(value);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});}
export async function all(store,index,key){const db=await openDB();return new Promise((resolve,reject)=>{const s=db.transaction(store).objectStore(store);const q=index?s.index(index).getAll(key):s.getAll();q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
export const uid=()=>{if(crypto.randomUUID)return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=[...b].map(n=>n.toString(16).padStart(2,'0')).join('');return [h.slice(0,8),h.slice(8,12),h.slice(12,16),h.slice(16,20),h.slice(20)].join('-');};
